import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static ArrayList<Long> heap = new ArrayList<>();

    static void push(long x) {
        heap.add(x);
        int i = heap.size() - 1;
        while (i > 0 && heap.get((i - 1) / 2) > heap.get(i)) {
            long t = heap.get((i - 1) / 2);
            heap.set((i - 1) / 2, heap.get(i));
            heap.set(i, t);
            i = (i - 1) / 2;
        }
    }

    static long pop() {
        long top = heap.get(0);
        long last = heap.remove(heap.size() - 1);
        if (!heap.isEmpty()) {
            heap.set(0, last);
            int i = 0;
            for (;;) {
                int small = i;
                for (int c = 2 * i + 1; c <= 2 * i + 2; c++) {
                    if (c < heap.size() && heap.get(c) < heap.get(small)) small = c;
                }
                if (small == i) break;
                long t = heap.get(i);
                heap.set(i, heap.get(small));
                heap.set(small, t);
                i = small;
            }
        }
        return top;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("push")) push(Long.parseLong(ops[i][1]));
            else if (op.equals("pop")) sb.append(pop()).append("\n");
            else sb.append(heap.get(0)).append("\n");
        }
        System.out.print(sb);
    }
}
